// TypeScript example: streaming with resume hook
import { RedwoodClient } from '@redwood/inference'
const client = new RedwoodClient({ retry: { maxRetries: 2, initialBackoffMs: 50 } })
const stream = client.streamGenerate({ prompt: 'Translate...', onResume: (ctx) => console.log('stream resumed', ctx) })
for await (const chunk of stream) { console.log(chunk.text) }
